import{ARIAQueryHandler}from"./AriaQueryHandler.js";import{customQueryHandlers}from"./CustomQueryHandler.js";import{PierceQueryHandler}from"./PierceQueryHandler.js";import{PQueryHandler}from"./PQueryHandler.js";import{TextQueryHandler}from"./TextQueryHandler.js";import{XPathQueryHandler}from"./XPathQueryHandler.js";export const BUILTIN_QUERY_HANDLERS=Object.freeze({aria:ARIAQueryHandler,pierce:PierceQueryHandler,xpath:XPathQueryHandler,text:TextQueryHandler});const QUERY_SEPARATORS=["=","/"];export function getQueryHandlerByName(e){return e in BUILTIN_QUERY_HANDLERS?BUILTIN_QUERY_HANDLERS[e]:customQueryHandlers.get(e)}export function getQueryHandlerAndSelector(e){for(const r of[customQueryHandlers.names().map((e=>[e,customQueryHandlers.get(e)])),Object.entries(BUILTIN_QUERY_HANDLERS)])for(const[t,n]of r)for(const r of QUERY_SEPARATORS){const a=`${t}${r}`;if(e.startsWith(a))return{updatedSelector:e=e.slice(a.length),QueryHandler:n}}return{updatedSelector:e,QueryHandler:PQueryHandler}}